/* @lc app=leetcode id=3845 lang=kotlin */ class Solution { fun upd(t: IntArray, v: Int, d: Int) = generateSequence(v + 32768) { it / 2 }.takeWhile { it >= 1 }.forEach { t[it] += d } fun qm(t: IntArray, x: Int): Int = (14 downTo 0).fold(1 to 0) { (node, res), b -> (1 - (x shr b and 1)).let { want -> if (t[node * 2 + want] > 0) (node * 2 + want) to (res or (1 shl b)) else (node * 2 + (1 - want)) to res } }.second fun maxXor(nums: IntArray, k: Int): Int = nums.runningFold(0) { a, b -> a xor b }.let { P -> IntArray(65536).let { t -> java.util.ArrayDeque<Int>().let { mx -> java.util.ArrayDeque<Int>().let { mn -> nums.indices.fold(0 to 0) { (l, best), r -> upd(t, P[r], 1).let { generateSequence { mx.peekLast()?.takeIf { nums[it] <= nums[r] } }.forEach { _ -> mx.pollLast() } }.let { mx.addLast(r) }.let { generateSequence { mn.peekLast()?.takeIf { nums[it] >= nums[r] } }.forEach { _ -> mn.pollLast() } }.let { mn.addLast(r) }.let { generateSequence(l) { ll -> if (nums[mx.peekFirst()] - nums[mn.peekFirst()] > k) upd(t, P[ll], -1).let { ll + 1 }.also { nl -> (if (mx.peekFirst() < nl) mx.pollFirst() else null).let { if (mn.peekFirst() < nl) mn.pollFirst() } } else null }.last() }.let { l2 -> l2 to maxOf(best, qm(t, P[r + 1])) } }.second } } } } }